const inputItem = items[0];
inputItem.binary.data.mimeType = `audio/mpeg`;
return inputItem;

// Get tomorrow's date in Asia/Manila (PST UTC+8)
const now = new Date();
const manilaOffset = 8 * 60; // UTC+8 in minutes
const utc = now.getTime() + now.getTimezoneOffset() * 60000;
const manila = new Date(utc + manilaOffset * 60000);
const tomorrow = new Date(manila);
tomorrow.setDate(manila.getDate() + 1);
const tomorrowStr = tomorrow.toISOString().split('T')[0]; // YYYY-MM-DD

const reminders = [];

for (const item of $input.all()) {
  const row = item.json;
  const apptDate = row['Appointment Date'];
  const reminderSent = row['Reminder Sent'];
  const status = row['Booking Status'];
  const phone = String(row['Phone'] || '').trim();
  const email = row['Email'];

  if (!apptDate || !phone || !email) continue;
  if (status === 'cancelled') continue;
  if (reminderSent) continue; // already sent

  // Parse appointment date (handles ISO format like 2026-03-17T15:00:00)
  const apptDateStr = apptDate.split('T')[0];
  if (apptDateStr !== tomorrowStr) continue;

  // Format time for display (12-hour)
  let displayTime = apptDate;
  try {
    const d = new Date(apptDate);
    displayTime = d.toLocaleTimeString('en-PH', {
      hour: 'numeric', minute: '2-digit', hour12: true, timeZone: 'Asia/Manila'
    });
  } catch(e) {}

  // Build reminder message using template
  const name    = row['Name'] || 'there';
  const topic   = row['Intake Form'] || 'your appointment';
  const message = `Hi ${name}! This is a friendly reminder that you have an appointment with Don tomorrow at ${displayTime} (Philippine Time).\n\nTopic: ${topic}\n\nSee you then! — Don's PA`;

  reminders.push({ json: { phone, name, email, displayTime, topic, message, appointmentDate: apptDate } });
}

return reminders;

